            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              [routeHeader]: process.env.CLAUDIAN_SESSION_TOOLS_ROUTE_ID,
            },
            body: JSON.stringify({ tool: spec.name, args, callerNativeId: ctx.sessionID }),
            signal: ctx.signal,
